/**
 * Climate anchor stations used by the residual-correction climate model.
 *
 * DATA HONESTY NOTE: every number in this file is an APPROXIMATE climate normal written from memory
 * (roughly 1981-2010 / 1991-2020 era public normals), rounded to whole degrees / 0.5 °C and to
 * round millimetre totals. They are good to about ±1-2 °C and ±10-25 % precipitation and are meant
 * to steer a procedural model, not to serve as reference data. The application labels values
 * derived from them as "inferred".
 *
 * Arrays run January -> December. Southern-hemisphere stations therefore show their warm season at
 * the start/end of the array (e.g. Sydney is warmest in January and coolest in July).
 *
 * `koppen` is the best-known published class for the station (Peel et al. 2007 / Beck et al. 2018
 * style). It may differ from `classifyKoppen()` on the tabulated values for borderline stations,
 * and because this codebase uses the classical -3 °C C/D boundary rather than Peel's 0 °C.
 *
 * Country is an ISO 3166-1 alpha-2 code (AQ = Antarctica, XX = international waters / disputed).
 */
import type { KoppenClass } from './koppen';

/** A climate reference station with approximate monthly normals. */
export interface ClimateAnchor {
  /** Stable, unique, snake_case identifier. */
  id: string;
  /** Human-readable station / city name. */
  name: string;
  /** ISO 3166-1 alpha-2 country code. */
  country: string;
  /** Latitude in degrees, positive north. */
  lat: number;
  /** Longitude in degrees, positive east. */
  lon: number;
  /** Station elevation above sea level in metres (approximate). */
  elevationM: number;
  /** 12 monthly mean temperatures (°C), January first. Approximate. */
  tempC: readonly number[];
  /** 12 monthly precipitation totals (mm), January first. Approximate. */
  precipMm: readonly number[];
  /** Best-known published Köppen-Geiger class for the station. */
  koppen: KoppenClass;
}

function a(
  id: string, name: string, country: string, lat: number, lon: number, elevationM: number,
  tempC: number[], precipMm: number[], koppen: KoppenClass,
): ClimateAnchor {
  if (tempC.length !== 12 || precipMm.length !== 12) {
    throw new Error(`Climate anchor "${id}" must have 12 temperature and 12 precipitation values`);
  }
  return { id, name, country, lat, lon, elevationM, tempC, precipMm, koppen };
}

